function highlightStock(ticker) {
    // Reset previous highlights
    d3.selectAll("tr").classed("highlighted", false);
    d3.selectAll(".bubble").classed("highlighted", false);

    // Highlight new row
    const selectedRow = d3.select(`#row-${ticker}`);
    selectedRow.classed("highlighted", true);

    // Scroll to row
    const tableContainer = document.getElementById('table-container');
    const rowElement = document.getElementById(`row-${ticker}`);
    if (rowElement) {
        tableContainer.scrollTo({
            top: rowElement.offsetTop - tableContainer.offsetTop - 100,
            behavior: 'smooth'
        });
    }

    // Highlight bubble
    d3.select(`#bubble-group-${ticker} circle`).classed("highlighted", true);

    // Draw price chart
    drawPriceChart(ticker);
}

function drawPriceChart(ticker) {
    const container = d3.select("#price-history-container");
    container.style("display", "block");
    d3.select("#price-chart-title").text(`Price History for ${ticker}`);

    const pcMargin = { top: 20, right: 30, bottom: 40, left: 50 };
    const pcWidth = container.node().clientWidth - pcMargin.left - pcMargin.right;
    const pcHeight = 300 - pcMargin.top - pcMargin.bottom;

    d3.select("#price-chart").selectAll("*").remove();

    const pcSvg = d3.select("#price-chart")
        .append("svg")
        .attr("width", pcWidth + pcMargin.left + pcMargin.right)
        .attr("height", pcHeight + pcMargin.top + pcMargin.bottom)
        .append("g")
        .attr("transform", `translate(${pcMargin.left},${pcMargin.top})`);

    d3.csv(`data/indiv-stock/${ticker}.csv`).then(priceData => {
        const parseDate = d3.timeParse("%Y-%m-%d");
        priceData.forEach(d => {
            d.date = parseDate(d.Date);
            d.close = +d.Close;
        });

        // Sort by date
        priceData.sort((a, b) => a.date - b.date);

        const x = d3.scaleTime()
            .domain(d3.extent(priceData, d => d.date))
            .range([0, pcWidth]);

        const y = d3.scaleLinear()
            .domain([d3.min(priceData, d => d.close) * 0.95, d3.max(priceData, d => d.close) * 1.05])
            .range([pcHeight, 0]);

        pcSvg.append("g")
            .attr("transform", `translate(0,${pcHeight})`)
            .call(d3.axisBottom(x));

        pcSvg.append("g")
            .call(d3.axisLeft(y));

        const line = d3.line()
            .x(d => x(d.date))
            .y(d => y(d.close));

        pcSvg.append("path")
            .datum(priceData)
            .attr("fill", "none")
            .attr("stroke", "#228be6")
            .attr("stroke-width", 2)
            .attr("d", line);

        // Add area
        const area = d3.area()
            .x(d => x(d.date))
            .y0(pcHeight)
            .y1(d => y(d.close));

        pcSvg.append("path")
            .datum(priceData)
            .attr("fill", "#e7f5ff")
            .attr("opacity", 0.5)
            .attr("d", area);

    }).catch(err => {
        console.error("Error loading price data for", ticker, err);
        d3.select("#price-chart").text("Price data not available for this stock.");
    });
}

